"""Competing-prefix calibration on held authors and train-only lexical banks."""
import argparse
from collections import Counter, defaultdict
from hashlib import sha256
from itertools import accumulate
import json
from math import fsum, log2
from pathlib import Path
import random
from statistics import mean
from string import ascii_lowercase

from vs.refcorpus import normalize, strip_gutenberg

AB=ascii_lowercase
TRAIN={'english':('pg2383.txt','5b1aa296e77d2c3dba23414d142136c6c9a762648a6470933f9190c4f1115d40'),
       'latin':('pg33849.txt','b9d4d33de51f661deb0137d3f9f191080d81959f21ae242d12b3ab0e278e8271'),
       'italian':('pg1012.txt','db0181a5820b1a60b93b87036351cad97b86ea3ab0d725b16dbc6017ab5ccd37'),
       'spanish':('pg16625.txt','9ffc47ebd6593c4c0c33b7f053f7b19c3ef389e57282437d30f6050ac6bafd09')}
LANGUAGE={'Middle English':'english','Latin':'latin','Old Italian':'italian','Old Castilian':'spanish'}
TOKENS=(15000,30000,60000)
SMOOTHINGS=(.5,1,2)
LENGTHS=tuple(range(4,9))
TEST=tuple(range(51201,51225))
ARMS=('uniform','length_only','length_frequency','latent')
CALIBRATION_COUNT=99

def digest(path):
    return sha256(path.read_bytes()).hexdigest()

def metric(words,alpha=1):
    n=len(words)
    counts=Counter(words)
    prefix=Counter()
    for w,c in counts.items():
        if len(w)>=2:
            prefix[w[:2]]+=c
    points=defaultdict(list)
    for w,c in counts.items():
        if len(w) in LENGTHS:
            numerator=log2(n-c+alpha)
            denominator=log2(prefix[w[:2]]-c+alpha)
            points[len(w)].append((log2(c/n),numerator-denominator,numerator,denominator))
    out={}
    for size in LENGTHS:
        xy=points[size]
        entry=dict(types=len(xy),information_mean=None,slope=None)
        if len(xy)>=100:
            xs,ys,up,down=zip(*xy)
            mx,my=mean(xs),mean(ys)
            xx=fsum((x-mx)**2 for x in xs)
            if xx:
                slope=lambda values:fsum((x-mx)*y for x,y in zip(xs,values))/xx
                pos,neg=slope(up),slope(down)
                s=slope(ys)
                assert abs(s-(pos-neg))<1e-12
                entry.update(information_mean=my,slope=s,numerator_slope=pos,
                             competitor_slope=neg)
        out[str(size)]=entry
    valid=[row for row in out.values() if row['slope'] is not None]
    joint=mean(row['information_mean'] for row in valid) if len(valid)==5 else None
    return dict(tokens=n,type_count=len(counts),supported_bins=len(valid),joint_score=joint,
                negative_slopes=sum(row['slope']<0 for row in valid),per_length=out)

def decision(record, threshold):
    if record['joint_score'] is None or threshold is None:
        return None
    return record['joint_score']<threshold and record['negative_slopes']>=4

class Sampler:
    def __init__(self,values,weights):
        self.values=list(values)
        self.ends=list(accumulate(weights))

    def take(self,rng,n=1):
        return rng.choices(self.values,cum_weights=self.ends,k=n)

def fit(path, language):
    raw_file,expected=TRAIN[language]
    p=path/raw_file
    assert digest(p)==expected
    tokens=normalize(strip_gutenberg(p.read_text(encoding='utf-8')),language).split()[:60000]
    counts=Counter(tokens)
    by_len=defaultdict(Counter)
    by_bin=defaultdict(Counter)
    total=Counter()
    for w,c in counts.items():
        if len(w)>=3:
            pre=w[:2]
            key=(len(w),c.bit_length())
            by_len[len(w)][pre]+=1
            by_bin[key][pre]+=1
            total[pre]+=1
    def sampler(c):
        return Sampler(c.keys(),c.values())
    length={k:sampler(v) for k,v in by_len.items()}
    joint={k:(v.total(),sampler(v)) for k,v in by_bin.items()}
    alphabet=''.join(sorted({c for w in counts for c in w}))
    return dict(training_tokens=len(tokens),alphabet=alphabet,counts=counts,length=length,
                joint=joint,fallback=sampler(total))

def random_word(rng,n,alphabet):
    return ''.join(rng.choices(alphabet,k=n))

def fresh_prefix(learned,arm,n,c,rng):
    if arm=='uniform' or rng.random()<1/26:
        return random_word(rng,2,learned['alphabet'])
    key=(n,c.bit_length())
    if arm in ('length_frequency','latent') and key in learned['joint']:
        size,sampler=learned['joint'][key]
        if rng.random()<size/(size+12):
            return sampler.take(rng)[0]
    return learned['length'].get(n,learned['fallback']).take(rng)[0]

def synthetic(learned,arm,number,seed):
    lexicon_offset=0x80736733 if arm=='latent' else 0
    structure=random.Random(seed ^ 0x41D05391 ^ lexicon_offset)
    tokens=random.Random(seed ^ 0x03FE9C5E)
    alphabet=learned['alphabet']
    by_len=defaultdict(list)
    for w,c in learned['counts'].items():
        by_len[len(w)].append(c)
    choices=[]
    exhausted=0
    for n,counts in sorted(by_len.items()):
        by_len_used=set()
        structure.shuffle(counts)
        if n<3:
            population=alphabet if n==1 else [a+b for a in alphabet for b in alphabet]
            words=structure.sample(list(population),len(counts))
            choices.extend(zip(words,counts))
            continue
        for c in counts:
            for attempt in range(10000):
                if attempt<=64:
                    pre=fresh_prefix(learned,arm,n,c,structure)
                    new=pre+random_word(structure,n-2,alphabet)
                else:
                    new=random_word(structure,n,alphabet)
                if new not in by_len_used:
                    break
            else:
                raise RuntimeError(f'Could not find unused artificial codeword of length {n}')
            exhausted+=attempt>64
            by_len_used.add(new)
            choices.append((new,c))
    assert sorted(w for w,_ in choices)==sorted(set(w for w,_ in choices))
    ws,weights=zip(*choices)
    whole=Sampler(ws,weights)
    if arm!='latent':
        text=whole.take(tokens,number)
    else:
        banks=defaultdict(list)
        for w,c in choices:
            banks[(ord(w[0])-97)%4].append((w,c))
        sub={i:Sampler(*zip(*rows)) for i,rows in banks.items()}
        assert len(sub)==4
        text=[]
        for offset in range(0,number,300):
            local=sub[tokens.randrange(4)]
            for _ in range(min(300,number-offset)):
                text.extend((local if tokens.random()<.25 else whole).take(tokens))
    return text,exhausted

def substitute(w,key):
    return w.translate(key)

def suffix_shift(word, seed, inverse=False):
    if len(word)<2:
        return word
    suffix=word[2:]
    h=sha256(f'{seed}/{suffix}'.encode('ascii')).digest()
    sign=-1 if inverse else 1
    return ''.join(AB[(ord(c)-97+sign*h[i])%26] for i,c in enumerate(word[:2]))+suffix

def encipher(source, mode, seed):
    if mode=='substitution':
        rng=random.Random(seed)
        chars=list(AB)
        rng.shuffle(chars)
        fwd=str.maketrans(AB,''.join(chars))
        back=str.maketrans(''.join(chars),AB)
        convert=lambda w:substitute(w,fwd)
        inverse=lambda w:substitute(w,back)
    elif mode=='reversal':
        convert=inverse=lambda w:w[::-1]
    elif mode=='suffix_shift':
        convert=lambda w:suffix_shift(w,seed)
        inverse=lambda w:suffix_shift(w,seed,inverse=True)
    else:
        raise ValueError(mode)
    table={w:convert(w) for w in set(source)}
    assert len(set(table.values()))==len(table)
    assert all(inverse(word)==orig and len(orig)==len(word) for orig,word in table.items())
    return [table[w] for w in source]

def compare(source, n, threshold, seed):
    result={}
    for mode in ('plain','substitution','reversal','suffix_shift','token_permutation'):
        if mode in ('plain','token_permutation'):
            current=source[:n]
            if mode=='token_permutation':
                random.Random(seed ^ 0xD99E51CB).shuffle(current)
        else:
            current=encipher(source[:n],mode,seed)
        ws={}
        for alpha in SMOOTHINGS:
            r=metric(current,alpha)
            if alpha==1 and n==30000:
                r['gate']=decision(r,threshold)
            ws[str(alpha)]=r
        result[mode]=ws
    assert result['substitution']==result['plain']
    def near(a,b):
        if isinstance(a,dict):
            return a.keys()==b.keys() and all(near(v,b[k]) for k,v in a.items())
        if isinstance(a,float):
            return abs(a-b)<1e-12
        return a==b
    assert near(result['token_permutation'],result['plain'])
    return result

def calibrate(learned,seed):
    draws=[]
    invalid=0
    cursor=0
    while len(draws)<CALIBRATION_COUNT and cursor<2*CALIBRATION_COUNT:
        sample,_=synthetic(learned,'uniform',30000,seed+cursor)
        r=metric(sample)
        if r['joint_score'] is None:
            invalid+=1
        else:
            draws.append(r['joint_score'])
        cursor+=1
    if len(draws)<CALIBRATION_COUNT:
        raise ValueError(f'Insufficient calibration support: {len(draws)} valid, {invalid} invalid')
    return dict(draws=draws,unsupported=invalid,threshold=sorted(draws)[4],seed_start=seed)

def null_models(learned,threshold,offset):
    out={}
    for arm in ARMS:
        scores=[]
        for seed in TEST:
            words,retries=synthetic(learned,arm,60000,seed+offset)
            grids={}
            for n in TOKENS:
                for alpha in SMOOTHINGS:
                    r=metric(words[:n],alpha)
                    grids[f'{n}/{alpha}']={k:r[k] for k in ('joint_score','supported_bins','negative_slopes')}
                    if n==30000 and alpha==1:
                        grids[f'{n}/{alpha}']['gate']=decision(r,threshold)
            scores.append(dict(seed=seed+offset,fallback_draws=retries,grids=grids))
        out[arm]=scores
    return out

def main():
    cli=argparse.ArgumentParser()
    cli.add_argument('raw',type=Path)
    cli.add_argument('readings',type=Path)
    opts=cli.parse_args()
    manifest=json.loads((opts.readings/'manifest.json').read_text())
    targets={name:metadata for name,metadata in manifest['works'].items()
             if metadata['tokens']>=30000 and metadata['language'] in LANGUAGE
             and not metadata['prior_prefix_overlap']}
    assert len(targets)>=4
    train_languages=sorted({LANGUAGE[m['language']] for m in targets.values()})
    calibrations={}
    models={}
    for i,lang in enumerate(train_languages):
        learned=fit(opts.raw,lang)
        calibration=calibrate(learned,590001+10003*i)
        calibrations[lang]=dict(training_tokens=learned['training_tokens'],training_types=len(learned['counts']),
                                alphabet=learned['alphabet'],
                                **calibration)
        models[lang]=null_models(learned,calibration['threshold'],100003*i)
    evaluations={}
    for i,(name,metadata) in enumerate(sorted(targets.items())):
        path=opts.readings/metadata['file']
        assert digest(path)==metadata['sha256']
        words=path.read_text().split()
        assert len(words)==metadata['tokens'] and all(w.isascii() and w.isalpha() and w.islower() for w in words)
        threshold=calibrations[LANGUAGE[metadata['language']]]['threshold']
        evaluations[name]={str(n):compare(words,n,threshold,328115+1007*i) for n in TOKENS if len(words)>=n}
    print(json.dumps(dict(inputs=targets,calibration=calibrations,artificial=models,works=evaluations),indent=2))

if __name__=='__main__':
    main()

scripts.endpoint_sensitivity.py:
"""Explicit endpoint conventions for the published uniqueness description.

This secondary analysis does not alter the registered prefix-bank comparison.
"""
import argparse
from collections import Counter, defaultdict
import json
from math import fsum, log2
from pathlib import Path
from statistics import mean

from prefix_bench import ARMS, LANGUAGE, LENGTHS, digest, fit, synthetic

WIDTHS=('unbounded_types','bounded_marker_rel_u','unbounded_rel_u',
        'mean_pre_unique','mean_add_one_inclusive')

def association(points):
    if len(points)<100:
        return {'types':len(points),'slope':None}
    x,y=zip(*points)
    mu=mean(x)
    xx=fsum((v-mu)**2 for v in x)
    if not xx:
        return {'types':len(points),'slope':None}
    return {'types':len(points),'slope':fsum((a-mu)*b for a,b in points)/xx}

def endpoint(words):
    frequencies=Counter(words)
    prefix_types=Counter()
    prefix_mass=Counter()
    for word,c in frequencies.items():
        for k in range(1,len(word)+1):
            prefix=word[:k]
            prefix_types[prefix]+=1
            prefix_mass[prefix]+=c
    n=len(words)
    lengths={l:defaultdict(list) for l in LENGTHS}
    beyond=Counter()
    max_error=0.
    for word,c in frequencies.items():
        length=len(word)
        if length not in lengths:
            continue
        record=lengths[length]
        x=log2(c/n)
        u=next((k for k in range(1,length+1) if prefix_types[word[:k]]==1), None)
        record['unbounded_types'].append((x,float(u is not None)))
        if u is None:
            beyond[str(length)]+=1
        else:
            record['unbounded_rel_u'].append((x,u/length))
        stop=u if u is not None else length+1
        record['bounded_marker_rel_u'].append((x,stop/(length+1)))
        previous=n-c
        components=[]
        for k in range(1,stop+1):
            current=0 if k>length else prefix_mass[word[:k]]-c
            components.append(log2((previous+1)/(current+1)))
            previous=current
        assert previous==0
        telescoped=log2(n-c+1)/stop
        max_error=max(max_error,abs(mean(components)-telescoped))
        record['mean_add_one_inclusive'].append((x,telescoped))
        if stop>1:
            last=prefix_mass[word[:stop-1]]-c
            assert last>0
            record['mean_pre_unique'].append((x,log2((n-c)/last)/(stop-1)))
    return dict(types_requiring_end_marker=dict(beyond),all_sample_types=len(frequencies),
                telescope_max_error=max_error,
                groups={str(length):{what:association(rows) for what,rows in record.items()}
                        for length,record in lengths.items()})

def main():
    ap=argparse.ArgumentParser()
    ap.add_argument('raw',type=Path)
    ap.add_argument('readings',type=Path)
    a=ap.parse_args()
    names=('boccaccio','caesar','gower','juan_manuel','malory')
    targets=json.loads((a.readings/'manifest.json').read_text())['works']
    independent={}
    for name in names:
        m=targets[name]
        p=a.readings/m['file']
        assert digest(p)==m['sha256']
        words=p.read_text().split()
        independent[name]={'start':endpoint(words[:30000])}
        if len(words)>=60000:
            independent[name]['next_nonoverlap']=endpoint(words[30000:60000])
    artificial={}
    for i,language in enumerate(sorted({LANGUAGE[targets[n]['language']] for n in names})):
        model=fit(a.raw,language)
        artificial[language]={}
        for arm in ARMS:
            artificial[language][arm]=[]
            for seed in range(830001,830009):
                words,_=synthetic(model,arm,30000,seed+96181*i)
                artificial[language][arm].append(dict(seed=seed+96181*i,**endpoint(words)))
    print(json.dumps(dict(independent_works=independent,artificial=artificial),indent=2))

if __name__=='__main__':
    main()

scripts.summarize.py:
"""Create a compact machine-readable summary from the three archived outputs."""
import argparse
from collections import Counter, defaultdict
import json
from pathlib import Path
from statistics import median

from prefix_bench import LANGUAGE

def read(path):
    return json.loads(path.read_text())

def compact_metric(groups):
    return {k:groups[k] for k in ('joint_score','supported_bins','negative_slopes')}

def artificial_summary(raw):
    out={}
    for lang,arms in raw.items():
        out[lang]={}
        for arm,items in arms.items():
            sensitivity={}
            for grid in items[0]['grids']:
                records=[x['grids'][grid] for x in items]
                values=[r['joint_score'] for r in records if r['joint_score'] is not None]
                sensitivity[grid]=dict(supported=len(values),samples=len(records),
                    score_range=[min(values),max(values)] if values else None,
                    score_median=median(values) if values else None,
                    four_negative=sum(r['negative_slopes']>=4 for r in records))
            outcomes=[x['grids']['30000/1'] for x in items]
            out[lang][arm]=dict(primary=[dict(seed=z['seed'],gate=q['gate'],**compact_metric(q))
                                          for z,q in zip(items,outcomes)],
                                 primary_supported=sum(x['gate'] is not None for x in outcomes),
                                 primary_passes=sum(x['gate'] is True for x in outcomes),
                                 retries_fallback=sum(x['fallback_draws'] for x in items),sensitivity=sensitivity)
    return out

def cohort_summary(cohort):
    out={}
    for lang,modes in cohort.items():
        out[lang]={}
        for key,rows in modes.items():
            outcomes=[r['outcome']['joint_score'] for r in rows]
            comparisons=[a for r in rows for a in r['score_below_held_works'].values()]
            out[lang][key]=dict(passes=sum(r['gate'] is True for r in rows),runs=len(rows),
                                 scores=[min(outcomes),median(outcomes),max(outcomes)],
                                 below_held=sum(comparisons),comparisons=len(comparisons),
                                 cases=[dict(seed=r['seed'],cohorts=r['cohorts'],types=r['types'],
                                             gate=r['gate'],score=r['outcome']['joint_score'],
                                             below=r['score_below_held_works']) for r in rows])
    return out

def uniq_summary(endpoint):
    synthetic={}
    for lang,arms in endpoint['artificial'].items():
        synthetic[lang]={}
        for arm,items in arms.items():
            summary=defaultdict(list)
            prefixed=[]
            for row in items:
                prefixed.append(sum(row['types_requiring_end_marker'].values()))
                for level in row['groups'].values():
                    for k,v in level.items():
                        if v['slope'] is not None:
                            summary[k].append(v['slope'])
            synthetic[lang][arm]=dict(
                 length_stratum_slopes={k:dict(negative=sum(q<0 for q in vals),positive=sum(q>0 for q in vals),
                                               total=len(vals),range=[min(vals),max(vals)])
                                       for k,vals in summary.items()},
                 marker_types_range=[min(prefixed),max(prefixed)],
                 max_telescoping_error=max(row['telescope_max_error'] for row in items))
    return dict(independent_works=endpoint['independent_works'],artificial=synthetic)

def main():
    ap=argparse.ArgumentParser()
    ap.add_argument('main',type=Path)
    ap.add_argument('cohort',type=Path)
    ap.add_argument('endpoint',type=Path)
    args=ap.parse_args()
    data=read(args.main)
    simple=artificial_summary(data['artificial'])
    cohort=read(args.cohort)
    rank=Counter()
    terminal_margins=[]
    works={}
    for w,sizes in data['works'].items():
        lang=LANGUAGE[data['inputs'][w]['language']]
        cutoff=data['calibration'][lang]['threshold']
        selected=sizes['30000']
        plain=selected['plain']['1']['joint_score']
        for z in cohort[lang]['terminal_cohort']:
            terminal_margins.append(plain-z['outcome']['joint_score'])
        for size,modes in sizes.items():
            for alpha,record in modes['plain'].items():
                score=record['joint_score']
                if score is None:
                    continue
                for arm,draws in data['artificial'][lang].items():
                    values=[d['grids'][size+'/'+alpha]['joint_score'] for d in draws]
                    values=[v for v in values if v is not None]
                    rank[arm,'compared']+=len(values)
                    rank[arm,'at_or_below']+=sum(v<=score for v in values)
                for transform in ('reversal','suffix_shift'):
                    encoded=modes[transform][alpha]['joint_score']
                    if encoded is not None:
                        rank[transform,'compared']+=1
                        rank[transform,'at_or_below']+=encoded<=score
        distance={}
        for k,x in simple[lang].items():
            q=[v['joint_score'] for v in x['primary'] if v['joint_score'] is not None]
            distance[k]=dict(total=len(q),at_or_below_work=sum(s<=plain for s in q),min_distance=min(q)-plain)
        work=dict(primary={k:v['1'] for k,v in selected.items()},threshold=cutoff,main_bank_comparison=distance,
                  sensitivities={size:{mode:{a:compact_metric(v) for a,v in variants.items()} for mode,variants in modes.items()}
                                 for size,modes in sizes.items()})
        works[w]=work
    ranking={arm:dict(compared=rank[arm,'compared'],at_or_below=rank[arm,'at_or_below'])
             for arm in sorted({arm for arm,_ in rank})}
    print(json.dumps(dict(inputs=data['inputs'],calibration=data['calibration'],works=works,artificial=simple,
                          cohort=cohort_summary(cohort),uniqueness=uniq_summary(read(args.endpoint)),
                          repeated_rank_sensitivities=ranking,
                          terminal_score_below_work_by=[min(terminal_margins),max(terminal_margins)]),indent=2))

if __name__=='__main__':
    main()
